use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(parts: Vec<string>, i: int) -> int {
    parts[i].parse::<int>().unwrap_or(0)
}

fn report<T: Shape>(s: T) -> int {
    let d = s.double_area()
    println("${s.name()} corners=${s.corners()} area2=${d}")
    d
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total: int = 0
    let mut best: int = -1
    let mut best_name = ""
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let kind = parts[0]
        let mut d: int = 0
        if kind == "square" {
            d = report(Square { s: num(parts, 1) })
        } else if kind == "rect" {
            d = report(Rect { w: num(parts, 1), h: num(parts, 2) })
        } else if kind == "rtri" {
            d = report(Rtri { a: num(parts, 1), b: num(parts, 2) })
        } else if kind == "trap" {
            d = report(Trap { a: num(parts, 1), b: num(parts, 2), h: num(parts, 3) })
        } else {
            continue
        }
        total += d
        if d > best {
            best = d
            best_name = kind
        }
    }
    if best < 0 {
        println("total area2=0")
        println("largest=none")
    } else {
        println("total area2=${total}")
        println("largest=${best_name} area2=${best}")
    }
}

